import{_ as a,o as s,c as i,ag as t}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"SoftForge Framework Manual","description":"","frontmatter":{},"headers":[],"relativePath":"en/02-framework-manual.md","filePath":"en/02-framework-manual.md"}'),o={name:"en/02-framework-manual.md"};function n(r,e,l,c,d,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="softforge-framework-manual" tabindex="-1">SoftForge Framework Manual <a class="header-anchor" href="#softforge-framework-manual" aria-label="Permalink to &quot;SoftForge Framework Manual&quot;">​</a></h1><blockquote><p><strong>Architecture, Design Patterns, and Internal Conventions</strong><br><em>Complete technical guide to the SoftForge ecosystem.</em></p></blockquote><hr><h2 id="_1-philosophy-why-vertical-slice-architecture" tabindex="-1">1. Philosophy: Why Vertical Slice Architecture? <a class="header-anchor" href="#_1-philosophy-why-vertical-slice-architecture" aria-label="Permalink to &quot;1. Philosophy: Why Vertical Slice Architecture?&quot;">​</a></h2><p>In traditional layered architecture (Controllers, Services, Repositories), features are scattered across distinct horizontal folders. When an AI agent attempts to create or edit a feature, it must juggle dozens of disparate files inside its context window, drastically increasing the chance of hallucination and unintended regressions.</p><p>In <strong>SoftForge</strong>, each business feature is completely self-contained in a vertical slice:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apps/api/src/slices/&lt;feature&gt;/</span></span>
<span class="line"><span>├── schemas.py       # OpenAPI contracts &amp; DTOs (Pydantic v2)</span></span>
<span class="line"><span>├── models.py        # ORM entities (SQLAlchemy 2.0 Async)</span></span>
<span class="line"><span>├── service.py       # Pure business logic</span></span>
<span class="line"><span>├── router.py        # HTTP routes &amp; dependencies</span></span>
<span class="line"><span>└── tests/           # Isolated integration tests</span></span></code></pre></div><hr><h2 id="_2-anatomy-of-a-vertical-slice" tabindex="-1">2. Anatomy of a Vertical Slice <a class="header-anchor" href="#_2-anatomy-of-a-vertical-slice" aria-label="Permalink to &quot;2. Anatomy of a Vertical Slice&quot;">​</a></h2><h3 id="_2-1-schemas-py-data-contracts" tabindex="-1">2.1 <code>schemas.py</code> (Data Contracts) <a class="header-anchor" href="#_2-1-schemas-py-data-contracts" aria-label="Permalink to &quot;2.1 \`schemas.py\` (Data Contracts)&quot;">​</a></h3><p>Defines strict inputs and outputs:</p><ul><li><code>CreateRequest</code> and <code>UpdateRequest</code> using Pydantic <code>Field(...)</code> validations.</li><li><code>Response</code> with <code>model_config = ConfigDict(from_attributes=True)</code> for direct ORM serialization.</li></ul><h3 id="_2-2-models-py-database-entities" tabindex="-1">2.2 <code>models.py</code> (Database Entities) <a class="header-anchor" href="#_2-2-models-py-database-entities" aria-label="Permalink to &quot;2.2 \`models.py\` (Database Entities)&quot;">​</a></h3><p>Inherits from <code>src.core.database.Base</code>:</p><ul><li>Automatically inherits <code>id</code> (cross-database UUID), <code>created_at</code>, and <code>updated_at</code>.</li><li>Strictly typed using <code>Mapped[...]</code> and <code>mapped_column(...)</code>.</li></ul><h3 id="_2-3-service-py-business-logic" tabindex="-1">2.3 <code>service.py</code> (Business Logic) <a class="header-anchor" href="#_2-3-service-py-business-logic" aria-label="Permalink to &quot;2.3 \`service.py\` (Business Logic)&quot;">​</a></h3><p>Pure async functions taking <code>session: AsyncSession</code>:</p><ul><li>Completely decoupled from HTTP concerns (no <code>Request</code> or <code>Response</code>).</li><li>Raises standardized exceptions (<code>NotFoundException</code>, <code>ForbiddenException</code>, <code>AppException</code>).</li></ul><h3 id="_2-4-router-py-http-layer" tabindex="-1">2.4 <code>router.py</code> (HTTP Layer) <a class="header-anchor" href="#_2-4-router-py-http-layer" aria-label="Permalink to &quot;2.4 \`router.py\` (HTTP Layer)&quot;">​</a></h3><p>Bridges logic to FastAPI:</p><ul><li>Applies security and RBAC guards (<code>require_workspace_role</code>).</li><li>Documents <code>response_model</code>, status codes, and Swagger tags.</li></ul><hr><h2 id="_3-multi-tenancy-and-role-based-access-control-rbac" tabindex="-1">3. Multi-Tenancy and Role-Based Access Control (RBAC) <a class="header-anchor" href="#_3-multi-tenancy-and-role-based-access-control-rbac" aria-label="Permalink to &quot;3. Multi-Tenancy and Role-Based Access Control (RBAC)&quot;">​</a></h2><p>SoftForge is built for B2B SaaS products with multi-workspace support:</p><ul><li><strong>Role Hierarchy:</strong><ol><li><code>Owner</code> (Level 4) — Full control over organization and billing.</li><li><code>Admin</code> (Level 3) — Manages members and project configurations.</li><li><code>Member</code> (Level 2) — Creates and edits projects and tasks.</li><li><code>Viewer</code> (Level 1) — Read-only access to resources.</li></ol></li></ul><hr><h2 id="_4-observability-structured-logging" tabindex="-1">4. Observability &amp; Structured Logging <a class="header-anchor" href="#_4-observability-structured-logging" aria-label="Permalink to &quot;4. Observability &amp; Structured Logging&quot;">​</a></h2><p>Powered by <strong>Loguru</strong> with automatic <strong>Correlation ID (<code>X-Request-ID</code>)</strong> propagation:</p><ul><li><strong>Development:</strong> Color-coded, highly readable logs showing file, function, and line.</li><li><strong>Production:</strong> Structured JSON logs ready for Datadog, Loki, or CloudWatch ingestion.</li><li>Every HTTP response includes <code>X-Request-ID</code> and <code>X-Process-Time</code>.</li></ul><hr><h2 id="_5-database-lifecycle-migrations-alembic" tabindex="-1">5. Database Lifecycle &amp; Migrations (Alembic) <a class="header-anchor" href="#_5-database-lifecycle-migrations-alembic" aria-label="Permalink to &quot;5. Database Lifecycle &amp; Migrations (Alembic)&quot;">​</a></h2><p>SoftForge uses <strong>Async Alembic</strong> engineered specifically for vertical slice architectures:</p><ul><li><strong>Dynamic Slice Model Discovery:</strong> <code>apps/api/alembic/env.py</code> calls <code>discover_and_import_models()</code>, auto-detecting any models defined in <code>apps/api/src/slices/*/models.py</code>.</li><li><strong>Constraint Naming Conventions:</strong> Enforces deterministic constraint names (<code>pk_...</code>, <code>fk_...</code>, <code>uq_...</code>, <code>ix_...</code>) for PostgreSQL integrity.</li><li><strong>Unified Tooling (<code>tools/scripts/migrate.py</code>):</strong><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate a new migration based on slice model changes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/migrate.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> makemigrations</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;add_priority_field&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Apply pending migrations to PostgreSQL</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/migrate.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Revert the latest migration</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/migrate.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> downgrade</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Emit raw offline SQL without connecting to the database</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/migrate.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql</span></span></code></pre></div></li><li><strong>Local Infrastructure:</strong> <code>docker-compose.yml</code> in the root starts the official PostgreSQL 16 instance with <code>docker compose up -d</code>.</li></ul>`,33)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
